SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.ar.root.articles"."articles" AS "articles"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')   ORDER BY "id" ASC NULLS LAST LIMIT 2 ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  (SELECT  coalesce(json_agg("_sub_query"."articles" ORDER BY "ob_col_1" ASC NULLS LAST), '[]' )  FROM  (SELECT  "_unnest_table"."articles" AS "articles", "_unnest_table"."ob_col_1" AS "ob_col_1" FROM UNNEST(array_agg("articles" ), array_agg("root.ar.root.articles.pg.id" )) AS "_unnest_table"("articles", "ob_col_1")    ORDER BY "ob_col_1" ASC NULLS LAST LIMIT 3 ) AS "_sub_query"      ) AS "articles" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.base"."id" AS "id", "_root.ar.root.articles.ar.articles.comments"."comments" AS "comments"       ) AS "_e"      ) ) AS "articles", "_root.ar.root.articles.base"."id" AS "root.ar.root.articles.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE ((("_root.base"."id") = ("author_id")) AND (("public"."article"."id") >= (('2')::integer)))   ORDER BY "id" ASC NULLS LAST  ) AS "_root.ar.root.articles.base" LEFT OUTER JOIN LATERAL (SELECT  (SELECT  coalesce(json_agg("_sub_query"."comments" ORDER BY "ob_col_1" DESC NULLS FIRST), '[]' )  FROM  (SELECT  "_unnest_table"."comments" AS "comments", "_unnest_table"."ob_col_1" AS "ob_col_1" FROM UNNEST(array_agg("comments" ), array_agg("root.ar.root.articles.ar.articles.comments.pg.id" )) AS "_unnest_table"("comments", "ob_col_1")    ORDER BY "ob_col_1" DESC NULLS FIRST LIMIT 2 ) AS "_sub_query"      ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.ar.articles.comments.base"."id" AS "id"       ) AS "_e"      ) ) AS "comments", "_root.ar.root.articles.ar.articles.comments.base"."id" AS "root.ar.root.articles.ar.articles.comments.pg.id" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.ar.root.articles.base"."id") = ("article_id"))   ORDER BY "id" DESC NULLS FIRST  ) AS "_root.ar.root.articles.ar.articles.comments.base"    ORDER BY "root.ar.root.articles.ar.articles.comments.pg.id" DESC NULLS FIRST  ) AS "_root.ar.root.articles.ar.articles.comments"      ) AS "_root.ar.root.articles.ar.articles.comments" ON ('true')    ORDER BY "root.ar.root.articles.pg.id" ASC NULLS LAST  ) AS "_root.ar.root.articles"      ) AS "_root.ar.root.articles" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"      
